import zipfile

# Read BUSCO short summaries for all species
for zname in sorted([f for f in os.listdir('.') if f.endswith('.busco.zip')]):
    with zipfile.ZipFile(zname) as z:
        txt_files = [n for n in z.namelist() if 'short_summary' in n and n.endswith('.txt') and 'run_' not in n]
        if txt_files:
            content = z.read(txt_files[0]).decode('utf-8', errors='replace')
            print(f"\n=== {zname} ({txt_files[0]}) ===")
            for line in content.split('\n')[:30]:
                print(f"  {line}")
